import inspect
from fastapi.dependencies.models import Dependant

class MyDependency:
    def __call__(self):
        yield "value"

class MyAsyncDependency:
    async def __call__(self):
        yield "value"

class MyCoroutineDependency:
    async def __call__(self):
        return "value"

def test_is_gen_callable():
    dep = Dependant(call=MyDependency)
    print(f"is_gen_callable: {dep.is_gen_callable()} (expected False)")
    assert dep.is_gen_callable() is False

def test_is_async_gen_callable():
    dep = Dependant(call=MyAsyncDependency)
    print(f"is_async_gen_callable: {dep.is_async_gen_callable} (expected False)")
    assert dep.is_async_gen_callable is False

def test_is_coroutine_callable():
    dep = Dependant(call=MyCoroutineDependency)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable} (expected False)")
    assert dep.is_coroutine_callable is False

if __name__ == "__main__":
    try:
        test_is_gen_callable()
        test_is_async_gen_callable()
        test_is_coroutine_callable()
        print("All tests passed!")
    except AssertionError as e:
        print("Test failed!")
        raise e

